class DuckDuckGoProvider(WebSearchProvider):
    """DuckDuckGo 搜索，无需 API Key。"""
    id = 'duckduckgo'

    def __init__(self, timeout=30, backend='auto'):
        self.timeout = timeout
        self.backend = backend

    def available(self):
        try:
            from ddgs import DDGS
            return True
        except ImportError:
            return False

    def search(self, query, max_results=5):
        try:
            from ddgs import DDGS
        except ImportError:
            return SearchResponse(sources=[], content=None)

        try:
            ddgs = DDGS(timeout=self.timeout)
            results = ddgs.text(
                query,
                max_results=max_results,
                backend=self.backend,
            )
            if not results:
                return SearchResponse(sources=[])

            sources = [
                SearchResult(
                    url=r.get('href', r.get('link', '')),
                    title=r.get('title', ''),
                    snippet=r.get('body', r.get('snippet', '')),
                )
                for r in results
            ]
            return SearchResponse(sources=sources, truncated=False)
        except Exception as e:
            logger.error('DuckDuckGo 搜索失败: %s', e)
            return SearchResponse(sources=[])


