# Bing 中国 Provider（国内可访问）
# ─────────────────────────────────────────
class BingChinaProvider(WebSearchProvider):
    """必应中国版搜索，国内可访问。"""
    id = 'bing_china'

    DEFAULT_BASE_URL = 'https://cn.bing.com'

    def __init__(self, base_url=None, timeout=15):
        self.base_url = (base_url or self.DEFAULT_BASE_URL).rstrip('/')
        self.timeout = timeout

    def available(self):
        """始终可用（无需 API Key）。"""
        return True

    def search(self, query, max_results=5):
        """通过必应中国版搜索。"""
        from urllib.parse import quote_plus
        url = f'{self.base_url}/search?q={quote_plus(query)}&count={max_results}'

        try:
            req = urllib.request.Request(
                url,
                headers={
                    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
                                  'AppleWebKit/537.36 (KHTML, like Gecko) '
                                  'Chrome/120.0.0.0 Safari/537.36',
                    'Accept-Language': 'zh-CN,zh;q=0.9',
                },
            )
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                html = resp.read().decode('utf-8', errors='replace')

            # 解析搜索结果
            sources = self._parse_results(html, max_results)
            return SearchResponse(sources=sources, truncated=False)
        except Exception as e:
            logger.error('Bing 中国搜索失败: %s', e)
            return SearchResponse(sources=[])

    def _parse_results(self, html, max_results):
        """从 Bing HTML 中提取搜索结果。"""
        from html.parser import HTMLParser

        class BingParser(HTMLParser):
            def __init__(self):
                super().__init__()
                self.results = []
                self.current = {}
                self.in_result = False
                self.in_title = False
                self.in_snippet = False
                self.depth = 0

            def handle_starttag(self, tag, attrs):
                attrs_dict = dict(attrs)
                # 搜索结果容器
                if tag == 'li' and 'b_algo' in attrs_dict.get('class', ''):
                    self.in_result = True
                    self.current = {'url': '', 'title': '', 'snippet': ''}
                    self.depth = 0
                elif self.in_result:
                    self.depth += 1
                    # 标题链接
                    if tag == 'a' and self.depth == 2:
                        href = attrs_dict.get('href', '')
                        if href.startswith('http'):
                            self.current['url'] = href
                            self.in_title = True
                    # 摘要
                    if tag == 'p' or tag == 'div':
                        cls = attrs_dict.get('class', '')
                        if 'b_caption' in cls or 'b_dList' in cls:
                            self.in_snippet = True

            def handle_endtag(self, tag):
                if self.in_result:
                    if tag == 'li':
                        if self.current.get('url'):
                            self.results.append(self.current)
                        self.in_result = False
                        self.current = {}
                    else:
                        self.depth -= 1
                        if tag == 'a':
                            self.in_title = False
                        if tag in ('p', 'div'):
                            self.in_snippet = False

            def handle_data(self, data):
                if self.in_result:
                    if self.in_title and not self.current.get('title'):
                        self.current['title'] = data.strip()
                    elif self.in_snippet and not self.current.get('snippet'):
                        self.current['snippet'] = data.strip()[:200]

        parser = BingParser()
        parser.feed(html)
        return [
            SearchResult(
                url=r['url'],
                title=r.get('title', ''),
                snippet=r.get('snippet', ''),
            )
            for r in parser.results[:max_results]
        ]


