# Perplexity Provider（高质量，OpenAI 兼容格式）
# ─────────────────────────────────────────
class PerplexityProvider(WebSearchProvider):
    """Perplexity Sonar 搜索，搜索+综合答案一步完成。

    使用 OpenAI 兼容的 /chat/completions 端点。
    """
    id = 'perplexity'

    DEFAULT_BASE_URL = 'https://api.perplexity.ai'
    DEFAULT_MODEL = 'sonar'
    DEFAULT_MAX_TOKENS = 1024

    def __init__(self, api_key=None, base_url=None, model=None, max_tokens=None):
        self.api_key = api_key or os.environ.get('PERPLEXITY_API_KEY', '')
        self.base_url = (base_url or self.DEFAULT_BASE_URL).rstrip('/')
        self.model = model or self.DEFAULT_MODEL
        self.max_tokens = max_tokens or self.DEFAULT_MAX_TOKENS

    def available(self):
        return bool(self.api_key)

    def search(self, query, max_results=5):
        if not self.api_key:
            return SearchResponse(sources=[])

        endpoint = f'{self.base_url}/chat/completions'
        body = {
            'model': self.model,
            'max_tokens': self.max_tokens,
            'messages': [{'role': 'user', 'content': query}],
        }

        try:
            req = urllib.request.Request(
                endpoint,
                data=json.dumps(body).encode('utf-8'),
                headers={
                    'Authorization': f'Bearer {self.api_key}',
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                },
            )
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = json.loads(resp.read().decode('utf-8'))

            # 解析响应（参考 deepseek-harness mapPerplexityResponse）
            content = data.get('choices', [{}])[0].get('message', {}).get('content', '')

            # 优先使用 search_results，回退到 citations
            search_results = data.get('search_results', [])
            if search_results:
                sources = [
                    SearchResult(
                        url=r.get('url', ''),
                        title=r.get('title', ''),
                        snippet=r.get('snippet', ''),
                        published_at=r.get('date'),
                    )
                    for r in search_results[:max_results]
                ]
            else:
                # 回退到 URL-only citations
                citations = data.get('citations', [])
                sources = [
                    SearchResult(url=url)
                    for url in citations[:max_results]
                ]

            return SearchResponse(
                sources=sources,
                content=content if content else None,
                truncated=False,
            )
        except Exception as e:
            logger.error('Perplexity 搜索失败: %s', e)
            return SearchResponse(sources=[])


# ─────────────────────────────────────────
# Provider 注册表（参考 deepseek-harness WebRuntime）
# ─────────────────────────────────────────
class WebSearchRegistry:
    """搜索 Provider 注册表与选择器。

    选择策略（参考 deepseek-harness resolveProvider）：
    - 配置了 provider_id → 精确匹配
    - 未配置 + 仅1个可用 → 自动选择
    - 未配置 + 多个可用 → 按优先级选择第一个
    - 无可用 → 返回 None
    """
    def __init__(self):
        self._providers = {}  # id -> provider
        self._configured_id = None

    def register(self, provider):
        """注册一个 Provider。"""
        self._providers[provider.id] = provider
        logger.debug('注册搜索 Provider: %s', provider.id)

    def set_configured(self, provider_id):
        """设置配置的默认 Provider。"""
        self._configured_id = provider_id

    def resolve(self):
        """解析当前可用的 Provider。"""
        # 精确匹配配置的 Provider
        if self._configured_id:
            provider = self._providers.get(self._configured_id)
            if provider and provider.available():
                return provider
            logger.warning('配置的搜索 Provider %s 不可用', self._configured_id)

        # 按注册顺序找第一个可用的
        for provider in self._providers.values():
            if provider.available():
                return provider

        return None

    def list_providers(self):
        """列出所有已注册的 Provider 及其状态。"""
        return [
            {'id': p.id, 'available': p.available()}
            for p in self._providers.values()
        ]


# ─────────────────────────────────────────
# 全局注册表实例
# ─────────────────────────────────────────
_registry = WebSearchRegistry()


def init_providers(config=None):
    """初始化搜索 Provider。

    config: 可选配置字典，支持以下键：
    - web_search_provider: 配置的默认 Provider id
    - perplexity_api_key: Perplexity API Key
    - perplexity_base_url: Perplexity 端点
    - perplexity_model: Perplexity 模型名
    """
    global _registry
    _registry = WebSearchRegistry()

    config = config or {}

    # 注册 Bing 中国版（国内可访问，优先使用）
    bing_timeout = config.get('web_search_timeout', 15)
    _registry.register(BingChinaProvider(timeout=bing_timeout))

    # 注册 DuckDuckGo（备用，但国内可能超时）
    ddg_timeout = config.get('web_search_timeout', 30)
    ddg_backend = config.get('web_search_backend', 'auto')
    _registry.register(DuckDuckGoProvider(timeout=ddg_timeout, backend=ddg_backend))

    # 注册 Perplexity（有 Key 时才可用）
    pplx_key = config.get('perplexity_api_key') or os.environ.get('PERPLEXITY_API_KEY', '')
    if pplx_key:
        _registry.register(PerplexityProvider(
            api_key=pplx_key,
            base_url=config.get('perplexity_base_url'),
            model=config.get('perplexity_model'),
        ))

    # 设置配置的默认 Provider
    configured = config.get('web_search_provider')
    if configured:
        _registry.set_configured(configured)
    elif pplx_key:
        # 有 Perplexity Key 时默认优先使用
        _registry.set_configured('perplexity')
    else:
        # 默认使用 Bing 中国版（国内可访问）
        _registry.set_configured('bing_china')


# ─────────────────────────────────────────
# 搜索结果格式化（参考 deepseek-harness formatSearchOutput）
# ─────────────────────────────────────────
def format_search_output(response, query):
    """将搜索响应格式化为模型面对的文本。"""
    parts = []

    # 综合答案
    if response.content:
        parts.append(response.content)

    # 来源列表
    if response.sources:
        lines = []
        for s in response.sources:
            label = s.title or s.url
            meta = []
            if s.snippet:
                meta.append(s.snippet)
            if s.published_at:
                meta.append(f'({s.published_at})')
            suffix = f' — {" ".join(meta)}' if meta else ''
            lines.append(f'- [{label}]({s.url}){suffix}')
        parts.append('Sources:\n' + '\n'.join(lines))
    elif not response.content:
        parts.append('No results found.')

    if response.truncated:
        parts.append(f'(Showing the first {len(response.sources)} sources. Refine the query for more.)')

    parts.append('Cite the relevant URLs above as markdown links in your answer.')
    return '\n\n'.join(parts)


# ─────────────────────────────────────────
# HTML → 纯文本转换器（用于 web_fetch）
# ─────────────────────────────────────────
class _HTMLTextParser(HTMLParser):
    """HTML → 纯文本转换器。"""
    def __init__(self):
        super().__init__()
        self._parts = []
        self._skip = 0

    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style', 'noscript'):
            self._skip += 1
        if tag in ('p', 'br', 'div', 'li', 'h1', 'h2', 'h3', 'h4'):
            self._parts.append('\n')

    def handle_endtag(self, tag):
        if tag in ('script', 'style', 'noscript') and self._skip > 0:
            self._skip -= 1
        if tag in ('p', 'div', 'li'):
            self._parts.append('\n')

    def handle_data(self, data):
        if self._skip:
            return
        text = ' '.join(str(data or '').split())
        if text:
            self._parts.append(text + ' ')

    def get_text(self):
        lines = []
        for line in ''.join(self._parts).splitlines():
            line = ' '.join(line.split())
            if line:
                lines.append(line)
        return '\n'.join(lines)


